다음 C 프로그램의 실행 결과를 예측하시오.

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 6;
    int *arr = (int *)malloc(sizeof(int) * n);

    for (int i = 0; i < n; i++) {
        arr[i] = (i + 1) * 2;
    }

    for (int i = 1; i < n; i++) {
        arr[i] = arr[i] + arr[i - 1];
    }

    int *sub = (int *)malloc(sizeof(int) * 3);
    for (int i = 0; i < 3; i++) {
        sub[i] = arr[n - 1 - i];
    }

    int sum = 0;
    for (int i = 0; i < 3; i++) {
        sum += sub[i];
    }

    printf("%d\n", arr[0]);
    printf("%d\n", arr[n - 1]);
    printf("%d\n", sum);

    free(arr);
    free(sub);

    return 0;
}

다음 Java 프로그램의 실행 결과를 예측하시오.

public class Main {
    public static void main(String[] args) {
        int[] arr = {5, 2, 9, 1, 6};
        int swapCount = 0;

        for (int i = 0; i < arr.length - 1; i++) {
            boolean swapped = false;
            for (int j = 0; j < arr.length - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                    swapCount++;
                    swapped = true;
                }
            }
            if (!swapped) {
                break;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < arr.length; i++) {
            sb.append(arr[i]);
            if (i != arr.length - 1) {
                sb.append(",");
            }
        }

        System.out.println(sb.toString());
        System.out.println(swapCount);
    }
}

